import { Link } from "react-router";
import logoHorizontal from "~/assets/logo/logo-horizontal.png";

interface LogoProps {
  className?: string;
  /** Rendered height in px; width follows the artwork's aspect ratio. */
  height?: number;
}

// Pixel size of logo-horizontal.png (generated by scripts/process-logo.py).
const SOURCE_WIDTH = 551;
const SOURCE_HEIGHT = 163;

export function Logo({ className, height = 44 }: LogoProps) {
  return (
    <Link to="/" className={className} aria-label="EntoMetrics Africa, home">
      <img
        src={logoHorizontal}
        alt=""
        width={Math.round((height * SOURCE_WIDTH) / SOURCE_HEIGHT)}
        height={height}
        style={{ height, width: "auto" }}
        decoding="async"
      />
    </Link>
  );
}
